package com.ruoyi.medical.persistence;
import com.ruoyi.medical.identity.*;import com.ruoyi.medical.contracts.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import jakarta.servlet.http.*;import org.springframework.security.core.Authentication;import org.springframework.beans.factory.ObjectProvider;import java.util.*;import java.util.function.Function;
public class RuntimeRetentionControllerTest {
 @Test void unauthenticatedWriteNeverReadsBody()throws Exception{var identities=mock(ApplicationSessionIdentity.class);var service=mock(RuntimeRetentionService.class);var request=mock(HttpServletRequest.class);var auth=mock(Authentication.class);when(request.getHeaders("X-Schema-Version")).thenReturn(Collections.enumeration(List.of("1.0.0")));when(request.getHeaders("X-Context-Revision")).thenReturn(Collections.enumeration(List.of("1")));when(request.getHeaders("Idempotency-Key")).thenReturn(Collections.enumeration(List.of("original-key-12345")));when(identities.requireCurrent(request,auth)).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));var controller=new RuntimeRetentionController(identities,service,new PermissionSchema(),mock(RuntimeRetentionReads.class),mock(RuntimeRetentionDecisions.class));assertThrows(TenantAccessException.class,()->controller.approve(request,mock(HttpServletResponse.class),auth));verify(request,never()).getInputStream();verifyNoInteractions(service);}
 @Test @SuppressWarnings("unchecked") void availabilityUsesActualControllerAndCurrentContext()throws Exception{var identities=mock(ApplicationSessionIdentity.class);var access=mock(EnterpriseAccess.class);ObjectProvider<RuntimeRetentionController> beans=mock(ObjectProvider.class);var subject=mock(ApplicationSessionIdentity.Verified.class);var admission=mock(EnterpriseAccess.Admission.class);when(admission.context()).thenReturn(new BusinessSessionProtocol.Context(RuntimeRetentionTest.id(1),"4","2","3"));when(access.execute(eq(subject),any())).thenAnswer(i->((Function<EnterpriseAccess.Admission,Object>)i.getArgument(1)).apply(admission));var request=mock(HttpServletRequest.class);var auth=mock(Authentication.class);when(request.getHeaders("X-Schema-Version")).thenReturn(Collections.enumeration(List.of("1.0.0")));when(request.getHeaders("X-Context-Revision")).thenAnswer(i->Collections.enumeration(List.of("4")));when(identities.requireCurrent(request,auth)).thenReturn(subject);var controller=new RuntimeRetentionAvailabilityController(identities,access,beans,new PermissionSchema());var response=mock(HttpServletResponse.class);assertFalse(controller.read(request,response,auth).at("/data/runtime_retention_enabled").asBoolean());verify(response).setHeader("X-Resource-Revision","4");when(beans.getIfAvailable()).thenReturn(mock(RuntimeRetentionController.class));when(request.getHeaders("X-Schema-Version")).thenReturn(Collections.enumeration(List.of("1.0.0")));assertTrue(controller.read(request,response,auth).at("/data/runtime_retention_enabled").asBoolean());}
 @Test void exactHandlersWriteProtocolErrors()throws Exception{var controller=new RuntimeRetentionController(mock(ApplicationSessionIdentity.class),mock(RuntimeRetentionService.class),new PermissionSchema(),mock(RuntimeRetentionReads.class),mock(RuntimeRetentionDecisions.class));var availability=new RuntimeRetentionAvailabilityController(mock(ApplicationSessionIdentity.class),mock(EnterpriseAccess.class),mock(ObjectProvider.class),new PermissionSchema());for(boolean discovery:List.of(false,true))for(ErrorCode code:List.of(ErrorCode.ACCESS_DENIED,ErrorCode.REVISION_CONFLICT,ErrorCode.CONTEXT_CHANGED,ErrorCode.SCHEMA_INVALID)){var response=new org.springframework.mock.web.MockHttpServletResponse();if(code==ErrorCode.SCHEMA_INVALID){if(discovery)availability.invalid(new SchemaRejection(code),response);else controller.invalid(new SchemaRejection(code),response);}else{if(discovery)availability.denied(new TenantAccessException(code),response);else controller.denied(new TenantAccessException(code),response);}assertEquals(code==ErrorCode.ACCESS_DENIED?403:code==ErrorCode.SCHEMA_INVALID?422:409,response.getStatus());assertEquals("1.0.0",response.getHeader("X-Schema-Version"));var body=new com.fasterxml.jackson.databind.ObjectMapper().readTree(response.getContentAsByteArray());assertEquals(response.getHeader("X-Request-Id"),body.required("request_id").textValue());assertEquals("1.0.0",body.required("schema_version").textValue());assertEquals(code.name(),body.required("code").textValue());assertTrue(body.required("code").isTextual());}}
 public static void main(String[]args)throws Exception{var t=new RuntimeRetentionControllerTest();t.unauthenticatedWriteNeverReadsBody();t.availabilityUsesActualControllerAndCurrentContext();t.exactHandlersWriteProtocolErrors();System.out.println("PASS 3 actual controller tests");}
}
